<script setup lang="ts">
import { BookOpen, ArrowRight } from 'lucide-vue-next'
import type { Restaurant } from '../../shared/domain'
const app=useApp();const {data,error,refresh}=await useFetch<Restaurant[]>('/api/catalog');const visits=computed(()=>[...app.history.value.visits].reverse().map(v=>({...v,restaurant:data.value?.find(r=>r.id===v.restaurantId),feedback:app.history.value.feedback.find(f=>f.visitId===v.id)})));useHead({title:'食べた記録 | ひとくち大阪',meta:[{name:'robots',content:'noindex'}]})
</script>
<template><section class="page narrow"><div class="section-heading"><div><div class="eyebrow">YOUR FOOD JOURNAL</div><h1>食べた記録</h1><p>おいしかった記憶が、次の出会いに。</p></div></div><div v-if="error" class="error">店舗を取得できませんでした。<button @click="refresh()">再試行</button></div><ClientOnly><div v-if="!visits.length" class="empty-state"><BookOpen :size="40"/><h2>最初の一軒を記録しよう。</h2><p>お店の詳細から「行った」を押すと記録できます。</p><NuxtLink to="/favorites" class="button primary">気になるお店を見る</NuxtLink></div><article v-for="v in visits" :key="v.id" class="visit-row"><img v-if="v.restaurant" :src="v.restaurant.coverImageUrl" :alt="v.restaurant.name"/><div><small>{{v.visitedAt}}</small><h2><NuxtLink v-if="v.restaurant" :to="`/restaurants/${v.restaurant.slug}`">{{v.restaurant.name}}</NuxtLink><span v-else>非公開になったお店</span></h2><p v-if="v.feedback" class="rating">{{'★'.repeat(v.feedback.satisfaction)}}<span class="muted">{{'☆'.repeat(5-v.feedback.satisfaction)}}</span></p><span v-else class="muted">感想を聞かせてください</span><NuxtLink :to="`/feedback/${v.id}`" class="text-link">{{v.feedback?'記録を見る・編集':'アンケートに回答'}}<ArrowRight :size="15"/></NuxtLink></div></article></ClientOnly></section></template>
